import{_ as e,C as i,o as t,c,a3 as h,b as r,w as g,a,E as d,a4 as s}from"./chunks/framework.MGD2uYU7.js";const B=JSON.parse('{"title":"08 — Truyền thông online: Kênh & luồng lead về Phần mềm tổng","description":"","frontmatter":{},"headers":[],"relativePath":"guide/08-truyen-thong-online.md","filePath":"guide/08-truyen-thong-online.md","lastUpdated":null}'),u={name:"guide/08-truyen-thong-online.md"};function l(m,n,b,p,k,C){const o=i("Mermaid");return t(),c("div",null,[n[1]||(n[1]=h('<h1 id="_08-—-truyen-thong-online-kenh-luong-lead-ve-phan-mem-tong" tabindex="-1">08 — Truyền thông online: Kênh &amp; luồng lead về Phần mềm tổng <a class="header-anchor" href="#_08-—-truyen-thong-online-kenh-luong-lead-ve-phan-mem-tong" aria-label="Permalink to &quot;08 — Truyền thông online: Kênh &amp; luồng lead về Phần mềm tổng&quot;">​</a></h1><p><strong>Dự án</strong>: Hệ thống phần mềm &amp; website cho CĐT An Phúc — dự án An Phúc Imperia <strong>Status</strong>: Draft gửi khách hàng rà soát — <strong>Updated</strong>: 2026-10-11 — <strong>Version</strong>: 2.0 <strong>Nguồn</strong>: Sheet <code>06_TRUYEN_THONG_ONLINE</code> (Google Sheet MAYogu × An Phúc)</p><blockquote><p>Bản đặc tả trung thực của sheet: bám sát từng kênh/hạng mục, không tự thêm. Phần chưa rõ đánh dấu 🟡.</p></blockquote><hr><h2 id="_1-gioi-thieu" tabindex="-1">1. Giới thiệu <a class="header-anchor" href="#_1-gioi-thieu" aria-label="Permalink to &quot;1. Giới thiệu&quot;">​</a></h2><p><strong>NGUỒN 05 – TRUYỀN THÔNG ONLINE.</strong> Các kênh online: <strong>website tổng của công ty, website NOXH, website NOTM và Facebook</strong>; kèm quy trình thiết lập nội dung/quảng cáo và liên kết phần mềm tổng.</p><p>Trong mô hình chung toàn hệ thống — <strong>&quot;5 nguồn lead → 1 Phần mềm tổng (CRM) với 1 ID khách hàng duy nhất&quot;</strong> (Sheet 01, xem doc <code>00</code> §4) — mảng Truyền thông online giữ hai vai trò:</p><ol><li><strong>Là Nguồn 05</strong>: trực tiếp phát sinh lead từ các kênh online (website tổng, website NOXH, website NOTM, Facebook).</li><li><strong>Điều phối việc đổ lead về CRM</strong>: chuẩn hóa nguồn/campaign khi đưa lead vào Phần mềm tổng, liên kết các kênh để lưu trữ lịch sử thông tin khách hàng theo <strong>một ID khách hàng/lead trung tâm</strong>.</li></ol><p><strong>Mục tiêu xuyên suốt (nguyên văn tinh thần sheet)</strong>: mọi lead từ các kênh online đều đổ về Phần mềm tổng; mỗi khách hàng có <strong>một ID khách hàng/lead trung tâm duy nhất</strong>, kèm lịch sử trao đổi, tiến trình xử lý và bản scan hồ sơ/tài liệu gắn theo ID đó.</p><p><strong>Nhãn trạng thái dùng trong doc</strong> (theo nguyên tắc trung thực toàn hệ thống — doc <code>00</code> §2):</p><table tabindex="0"><thead><tr><th>Nhãn</th><th>Ý nghĩa</th></tr></thead><tbody><tr><td>✅ <strong>ĐÃ CHỐT</strong></td><td>Sheet khẳng định rõ.</td></tr><tr><td>🟡 <strong>CẦN XÁC NHẬN / CẦN BỔ SUNG</strong></td><td>Sheet để trống hoặc chưa nói rõ — <strong>không tự suy diễn</strong>.</td></tr><tr><td>🔵 <strong>ĐỀ XUẤT (chưa duyệt)</strong></td><td>Sheet ghi dạng đề xuất — phải được CĐT xác nhận trước khi đưa vào phạm vi.</td></tr></tbody></table><p><strong>Quy ước định danh</strong>: mã mảng <code>TTOL</code>; yêu cầu chức năng (nếu cần) đánh số <code>FR-TTOL-nn</code>.</p><hr><h2 id="_2-bang-yeu-cau-goc-—-7-hang-muc-faithful-1‐1-voi-sheet" tabindex="-1">2. Bảng yêu cầu gốc — 7 hạng mục (faithful 1‑1 với sheet) <a class="header-anchor" href="#_2-bang-yeu-cau-goc-—-7-hang-muc-faithful-1‐1-voi-sheet" aria-label="Permalink to &quot;2. Bảng yêu cầu gốc — 7 hạng mục (faithful 1‑1 với sheet)&quot;">​</a></h2><p>Bảng dưới đây <strong>giữ đúng ngôn từ sheet</strong> <code>06_TRUYEN_THONG_ONLINE</code>, không thêm/bớt nội dung:</p><table tabindex="0"><thead><tr><th>STT</th><th>KÊNH / HẠNG MỤC</th><th>MỤC ĐÍCH / NỘI DUNG</th><th>CÁCH ĐỔ LEAD VỀ CRM</th><th>LỊCH SỬ / DỮ LIỆU</th><th>CÔNG VIỆC</th></tr></thead><tbody><tr><td>1</td><td>Website tổng của công ty</td><td>Kênh online giới thiệu tổng thể.</td><td>Lead từ website → phần mềm tổng.</td><td>Thông tin khách hàng + lịch sử trao đổi</td><td>Đã gửi đề xuất sơ bộ cho anh Phúc. 🟡</td></tr><tr><td>2</td><td>Website sản phẩm NOXH</td><td>Thu lead, tiếp nhận và xử lý hồ sơ NOXH.</td><td>Lead + hồ sơ + trạng thái → phần mềm tổng.</td><td>Lịch sử trao đổi, tiến trình xử lý, bản scan theo ID khách hàng</td><td>Sheet 03.</td></tr><tr><td>3</td><td>Website sản phẩm NOTM</td><td>Thu lead và hỗ trợ quy trình bán hàng NOTM.</td><td>Lead + sản phẩm quan tâm + lịch sử → phần mềm tổng.</td><td>Lịch sử tư vấn/giao dịch</td><td>Sheet 04.</td></tr><tr><td>4</td><td>Facebook</td><td>Kênh truyền thông online/thu lead.</td><td>Lead/inbox/form/campaign → phần mềm tổng.</td><td>Nội dung trao đổi, nguồn chiến dịch</td><td><em>(trống)</em> 🟡</td></tr><tr><td>5</td><td>Thiết lập kênh online</td><td>Thiết lập web, Facebook; lên nội dung và chạy quảng cáo.</td><td>Chuẩn hóa nguồn/campaign khi đưa lead vào CRM.</td><td>Nguồn, lịch sử tương tác</td><td>Phối hợp đơn vị quảng cáo.</td></tr><tr><td>6</td><td>Tài liệu bán hàng online</td><td>Phối hợp IT + Thiết kế đề xuất tài liệu bán hàng online.</td><td>Gắn nguồn tài liệu/landing page vào lead nếu có.</td><td>Tài liệu và nguồn truy cập</td><td><em>(trống)</em> 🟡</td></tr><tr><td>7</td><td>Liên kết phần mềm tổng</td><td>Liên kết các kênh để lưu trữ lịch sử thông tin khách hàng.</td><td>Một ID khách hàng/lead trung tâm.</td><td>Lịch sử trao đổi + tiến trình xử lý hồ sơ</td><td>Kết hợp lưu bản scan hồ sơ/tài liệu theo ID khách hàng.</td></tr></tbody></table><blockquote><p>Ghi chú nhãn: 🟡 đặt ở các ô sheet <strong>để trống</strong> hoặc <strong>chưa rõ</strong> (hạng mục 1 — mới &quot;gửi đề xuất sơ bộ&quot;, chưa ghi nhận phản hồi; hạng mục 4, 6 — cột CÔNG VIỆC trống). Các ô còn lại là nội dung ✅ sheet đã nêu.</p></blockquote><hr><h2 id="_3-dien-giai-tung-hang-muc-chi-dua-tren-sheet" tabindex="-1">3. Diễn giải từng hạng mục (chỉ dựa trên sheet) <a class="header-anchor" href="#_3-dien-giai-tung-hang-muc-chi-dua-tren-sheet" aria-label="Permalink to &quot;3. Diễn giải từng hạng mục (chỉ dựa trên sheet)&quot;">​</a></h2><h3 id="_3-1-hang-muc-1-—-website-tong-cua-cong-ty-✅-noi-dung-🟡-trang-thai-cong-viec" tabindex="-1">3.1 Hạng mục 1 — Website tổng của công ty ✅ (nội dung) / 🟡 (trạng thái công việc) <a class="header-anchor" href="#_3-1-hang-muc-1-—-website-tong-cua-cong-ty-✅-noi-dung-🟡-trang-thai-cong-viec" aria-label="Permalink to &quot;3.1 Hạng mục 1 — Website tổng của công ty ✅ (nội dung) / 🟡 (trạng thái công việc)&quot;">​</a></h3><ul><li><strong>Vai trò</strong>: kênh online <strong>giới thiệu tổng thể</strong> về công ty/dự án — chính là <strong>Web Chủ đầu tư (Nguồn 01)</strong> trong mô hình 5 nguồn; đặc tả nội dung &amp; media chi tiết tại doc <code>03-web-chu-dau-tu.md</code>.</li><li><strong>Luồng lead</strong>: lead phát sinh từ website (form đăng ký nhận thông tin…) → <strong>phần mềm tổng</strong>. Dữ liệu kèm theo: <strong>thông tin khách hàng + lịch sử trao đổi</strong>.</li><li><strong>Trạng thái công việc (nguyên văn sheet)</strong>: <em>&quot;Đã gửi đề xuất sơ bộ cho anh Phúc.&quot;</em> → 🟡 <strong>đang chờ phản hồi</strong>; nội dung đề xuất và kết quả chưa được ghi trong sheet — xem OQ‑TTOL‑04 (§5). Tài liệu <strong>không tự suy diễn</strong> đề xuất này gồm những gì.</li></ul><h3 id="_3-2-hang-muc-2-—-website-san-pham-noxh-✅" tabindex="-1">3.2 Hạng mục 2 — Website sản phẩm NOXH ✅ <a class="header-anchor" href="#_3-2-hang-muc-2-—-website-san-pham-noxh-✅" aria-label="Permalink to &quot;3.2 Hạng mục 2 — Website sản phẩm NOXH ✅&quot;">​</a></h3><ul><li><strong>Vai trò</strong>: <strong>thu lead, tiếp nhận và xử lý hồ sơ NOXH</strong> — chính là <strong>Web Nhà ở xã hội (Nguồn 02)</strong>; quy trình nghiệp vụ 20 bước, trạng thái hồ sơ, phân quyền chi tiết tại doc <code>04-web-noxh.md</code> (sheet ghi cột CÔNG VIỆC: <em>&quot;Sheet 03&quot;</em> — tức tab <code>03_WEB_NOXH</code>).</li><li><strong>Luồng lead</strong>: <strong>lead + hồ sơ + trạng thái → phần mềm tổng</strong>. Đây là luồng &quot;nặng&quot; dữ liệu nhất trong các kênh online: không chỉ thông tin khách mà cả <strong>bộ hồ sơ và trạng thái xử lý</strong>.</li><li><strong>Lịch sử / dữ liệu</strong>: lịch sử trao đổi, <strong>tiến trình xử lý</strong>, <strong>bản scan theo ID khách hàng</strong>.</li></ul><h3 id="_3-3-hang-muc-3-—-website-san-pham-notm-✅" tabindex="-1">3.3 Hạng mục 3 — Website sản phẩm NOTM ✅ <a class="header-anchor" href="#_3-3-hang-muc-3-—-website-san-pham-notm-✅" aria-label="Permalink to &quot;3.3 Hạng mục 3 — Website sản phẩm NOTM ✅&quot;">​</a></h3><ul><li><strong>Vai trò</strong>: <strong>thu lead và hỗ trợ quy trình bán hàng NOTM</strong> — chính là <strong>Web Nhà ở thương mại (Nguồn 03)</strong>; quy trình bán hàng 8 bước chi tiết tại doc <code>05-web-notm.md</code> (sheet ghi cột CÔNG VIỆC: <em>&quot;Sheet 04&quot;</em> — tức tab <code>04_WEB_NOTM</code>).</li><li><strong>Luồng lead</strong>: <strong>lead + sản phẩm quan tâm + lịch sử → phần mềm tổng</strong>.</li><li><strong>Lịch sử / dữ liệu</strong>: <strong>lịch sử tư vấn/giao dịch</strong>.</li></ul><h3 id="_3-4-hang-muc-4-—-facebook-✅-noi-dung-🟡-cong-viec-co-che-ky-thuat" tabindex="-1">3.4 Hạng mục 4 — Facebook ✅ (nội dung) / 🟡 (công việc &amp; cơ chế kỹ thuật) <a class="header-anchor" href="#_3-4-hang-muc-4-—-facebook-✅-noi-dung-🟡-cong-viec-co-che-ky-thuat" aria-label="Permalink to &quot;3.4 Hạng mục 4 — Facebook ✅ (nội dung) / 🟡 (công việc &amp; cơ chế kỹ thuật)&quot;">​</a></h3><ul><li><strong>Vai trò</strong>: kênh truyền thông online / <strong>thu lead</strong>.</li><li><strong>Luồng lead (nguyên văn sheet)</strong>: <strong>lead/inbox/form/campaign → phần mềm tổng</strong>. Sheet nêu 4 dạng đầu vào (lead, inbox, form, campaign) nhưng <strong>không nói rõ cơ chế kỹ thuật</strong> (API/form connector/webhook/nhập tay…) — 🟡 xem OQ‑TTOL‑01 (§5); tài liệu không tự chọn phương án.</li><li><strong>Lịch sử / dữ liệu</strong>: <strong>nội dung trao đổi, nguồn chiến dịch</strong> → khi vào CRM phải được <strong>chuẩn hóa nguồn/campaign</strong> (liên hệ hạng mục 5).</li><li><strong>Cột CÔNG VIỆC</strong>: sheet để <strong>trống</strong> — 🟡 xem OQ‑TTOL‑02 (§5).</li></ul><h3 id="_3-5-hang-muc-5-—-thiet-lap-kenh-online-✅" tabindex="-1">3.5 Hạng mục 5 — Thiết lập kênh online ✅ <a class="header-anchor" href="#_3-5-hang-muc-5-—-thiet-lap-kenh-online-✅" aria-label="Permalink to &quot;3.5 Hạng mục 5 — Thiết lập kênh online ✅&quot;">​</a></h3><ul><li><strong>Nội dung công việc</strong>: <strong>thiết lập web, Facebook; lên nội dung và chạy quảng cáo</strong>.</li><li><strong>Yêu cầu tích hợp</strong>: <strong>chuẩn hóa nguồn/campaign khi đưa lead vào CRM</strong> — tức mọi lead từ các kênh/quảng cáo phải mang thông tin nguồn (kênh nào, campaign nào) ở định dạng thống nhất trong CRM. Sheet <strong>không nêu định dạng chuẩn cụ thể</strong> — 🟡 xem OQ‑TTOL‑03 (§5).</li><li><strong>Lịch sử / dữ liệu</strong>: <strong>nguồn, lịch sử tương tác</strong>.</li><li><strong>Công việc (nguyên văn)</strong>: <strong>&quot;Phối hợp đơn vị quảng cáo.&quot;</strong> — sheet không nêu tên đơn vị quảng cáo và ai phụ trách — 🟡 xem OQ‑TTOL‑02 (§5).</li></ul><h3 id="_3-6-hang-muc-6-—-tai-lieu-ban-hang-online-✅-noi-dung-🟡-cong-viec" tabindex="-1">3.6 Hạng mục 6 — Tài liệu bán hàng online ✅ (nội dung) / 🟡 (công việc) <a class="header-anchor" href="#_3-6-hang-muc-6-—-tai-lieu-ban-hang-online-✅-noi-dung-🟡-cong-viec" aria-label="Permalink to &quot;3.6 Hạng mục 6 — Tài liệu bán hàng online ✅ (nội dung) / 🟡 (công việc)&quot;">​</a></h3><ul><li><strong>Nội dung công việc</strong>: <strong>phối hợp IT + Thiết kế đề xuất tài liệu bán hàng online</strong>.</li><li><strong>Yêu cầu tích hợp</strong>: <strong>gắn nguồn tài liệu/landing page vào lead nếu có</strong> — khi lead phát sinh từ một tài liệu/landing page cụ thể, thông tin nguồn đó được gắn vào lead trong CRM.</li><li><strong>Lịch sử / dữ liệu</strong>: <strong>tài liệu và nguồn truy cập</strong>.</li><li><strong>Cột CÔNG VIỆC</strong>: sheet để <strong>trống</strong> — 🟡 chưa rõ đầu việc/trách nhiệm cụ thể ngoài nội dung đã nêu ở cột MỤC ĐÍCH.</li></ul><h3 id="_3-7-hang-muc-7-—-lien-ket-phan-mem-tong-✅" tabindex="-1">3.7 Hạng mục 7 — Liên kết phần mềm tổng ✅ <a class="header-anchor" href="#_3-7-hang-muc-7-—-lien-ket-phan-mem-tong-✅" aria-label="Permalink to &quot;3.7 Hạng mục 7 — Liên kết phần mềm tổng ✅&quot;">​</a></h3><ul><li><strong>Mục đích</strong>: <strong>liên kết các kênh để lưu trữ lịch sử thông tin khách hàng</strong> — đây là hạng mục &quot;chốt&quot; mô hình của Nguồn 05.</li><li><strong>Nguyên tắc trung tâm (nguyên văn sheet)</strong>: <strong>&quot;Một ID khách hàng/lead trung tâm.&quot;</strong> Mọi lead/khách từ Website tổng, Web NOXH, Web NOTM, Facebook khi về CRM phải quy về <strong>một ID duy nhất</strong> (khớp chức năng trung tâm của Phần mềm tổng — doc <code>02-phan-mem-tong-crm.md</code>).</li><li><strong>Lịch sử / dữ liệu</strong>: <strong>lịch sử trao đổi + tiến trình xử lý hồ sơ</strong>.</li><li><strong>Công việc (nguyên văn)</strong>: <strong>&quot;Kết hợp lưu bản scan hồ sơ/tài liệu theo ID khách hàng.&quot;</strong></li></ul><hr><h2 id="_4-so-đo-luong-lead-cac-kenh-online-→-phan-mem-tong" tabindex="-1">4. Sơ đồ luồng lead các kênh online → Phần mềm tổng <a class="header-anchor" href="#_4-so-đo-luong-lead-cac-kenh-online-→-phan-mem-tong" aria-label="Permalink to &quot;4. Sơ đồ luồng lead các kênh online → Phần mềm tổng&quot;">​</a></h2><p>Chỉ gồm <strong>đúng các kênh sheet nêu</strong> (Website tổng, Web NOXH, Web NOTM, Facebook). Sheet không nêu kênh nào khác nên sơ đồ <strong>không vẽ thêm</strong> kênh khác:</p>',36)),(t(),r(s,null,{default:g(()=>[d(o,{id:"mermaid-429",class:"mermaid",graph:"flowchart%20LR%0A%20%20W1%5B%22Website%20t%E1%BB%95ng%20c%E1%BB%A7a%20c%C3%B4ng%20ty%3Cbr%2F%3E(gi%E1%BB%9Bi%20thi%E1%BB%87u%20t%E1%BB%95ng%20th%E1%BB%83)%22%5D%0A%20%20W2%5B%22Website%20s%E1%BA%A3n%20ph%E1%BA%A9m%20NOXH%3Cbr%2F%3E(thu%20lead%20%2B%20h%E1%BB%93%20s%C6%A1%20NOXH)%22%5D%0A%20%20W3%5B%22Website%20s%E1%BA%A3n%20ph%E1%BA%A9m%20NOTM%3Cbr%2F%3E(thu%20lead%20%2B%20b%C3%A1n%20h%C3%A0ng%20NOTM)%22%5D%0A%20%20FB%5B%22Facebook%3Cbr%2F%3E(lead%20%2F%20inbox%20%2F%20form%20%2F%20campaign)%22%5D%0A%20%20CRM%5B(%22PH%E1%BA%A6N%20M%E1%BB%80M%20T%E1%BB%94NG%20%E2%80%94%20CRM%3Cbr%2F%3EM%E1%BB%99t%20ID%20kh%C3%A1ch%20h%C3%A0ng%2Flead%20trung%20t%C3%A2m%3Cbr%2F%3EL%E1%BB%8Bch%20s%E1%BB%AD%20trao%20%C4%91%E1%BB%95i%20%2B%20ti%E1%BA%BFn%20tr%C3%ACnh%20x%E1%BB%AD%20l%C3%BD%3Cbr%2F%3E%2B%20b%E1%BA%A3n%20scan%20h%E1%BB%93%20s%C6%A1%2Ft%C3%A0i%20li%E1%BB%87u%20theo%20ID%22)%5D%0A%0A%20%20W1%20--%20%22Lead%3A%20th%C3%B4ng%20tin%20KH%20%2B%20l%E1%BB%8Bch%20s%E1%BB%AD%20trao%20%C4%91%E1%BB%95i%22%20--%3E%20CRM%0A%20%20W2%20--%20%22Lead%20%2B%20h%E1%BB%93%20s%C6%A1%20%2B%20tr%E1%BA%A1ng%20th%C3%A1i%22%20--%3E%20CRM%0A%20%20W3%20--%20%22Lead%20%2B%20s%E1%BA%A3n%20ph%E1%BA%A9m%20quan%20t%C3%A2m%20%2B%20l%E1%BB%8Bch%20s%E1%BB%AD%22%20--%3E%20CRM%0A%20%20FB%20--%20%22Lead%2Finbox%2Fform%2Fcampaign%20%F0%9F%9F%A1%20c%C6%A1%20ch%E1%BA%BF%20k%E1%BB%B9%20thu%E1%BA%ADt%20ch%C6%B0a%20r%C3%B5%22%20--%3E%20CRM%0A"})]),fallback:g(()=>[...n[0]||(n[0]=[a(" Loading... ",-1)])]),_:1})),n[2]||(n[2]=h('<blockquote><p>Ghi chú: việc <strong>chuẩn hóa nguồn/campaign</strong> (hạng mục 5) và <strong>gắn nguồn tài liệu/landing page</strong> (hạng mục 6) áp dụng cho lead từ <strong>mọi kênh</strong> ở trên khi đưa vào CRM.</p></blockquote><hr><h2 id="_5-can-xac-nhan-oq-—-sheet-chua-ro-khong-tu-tra-loi" tabindex="-1">5. Cần xác nhận (OQ) — sheet chưa rõ, KHÔNG tự trả lời <a class="header-anchor" href="#_5-can-xac-nhan-oq-—-sheet-chua-ro-khong-tu-tra-loi" aria-label="Permalink to &quot;5. Cần xác nhận (OQ) — sheet chưa rõ, KHÔNG tự trả lời&quot;">​</a></h2><p>Các điểm dưới đây <strong>không có câu trả lời trong sheet</strong>; tài liệu nêu nguyên trạng để CĐT/MAYogu chốt, sẽ tổng hợp vào doc <code>09-open-questions.md</code>:</p><table tabindex="0"><thead><tr><th>Mã</th><th>Câu hỏi</th><th>Căn cứ (vị trí trong sheet)</th><th>Ai trả lời</th></tr></thead><tbody><tr><td>🟡 <strong>OQ‑TTOL‑01</strong></td><td><strong>Cơ chế kỹ thuật đổ lead từ Facebook về CRM</strong>: sheet chỉ ghi &quot;Lead/inbox/form/campaign → phần mềm tổng&quot;, không nói rõ dùng API, form connector, webhook hay nhập tay.</td><td>Hạng mục 4, cột CÁCH ĐỔ LEAD VỀ CRM</td><td>CĐT + MAYogu (kỹ thuật)</td></tr><tr><td>🟡 <strong>OQ‑TTOL‑02</strong></td><td><strong>Ai phụ trách chạy quảng cáo / đơn vị quảng cáo nào?</strong> Sheet chỉ ghi &quot;Phối hợp đơn vị quảng cáo&quot; (hạng mục 5) và để trống cột CÔNG VIỆC ở hạng mục 4, 6.</td><td>Hạng mục 4, 5, 6 — cột CÔNG VIỆC</td><td>CĐT</td></tr><tr><td>🟡 <strong>OQ‑TTOL‑03</strong></td><td><strong>Định dạng &quot;chuẩn hóa nguồn/campaign&quot; trong CRM</strong>: sheet yêu cầu chuẩn hóa nhưng chưa nêu quy ước đặt tên nguồn/campaign, trường dữ liệu, danh mục kênh.</td><td>Hạng mục 5, cột CÁCH ĐỔ LEAD VỀ CRM</td><td>CĐT + MAYogu</td></tr><tr><td>🟡 <strong>OQ‑TTOL‑04</strong></td><td><strong>&quot;Đã gửi đề xuất sơ bộ cho anh Phúc&quot;</strong> — nội dung đề xuất là gì và phản hồi của anh Phúc ra sao? Sheet chỉ ghi trạng thái, chưa ghi nhận kết quả.</td><td>Hạng mục 1, cột CÔNG VIỆC</td><td>MAYogu + CĐT (anh Phúc)</td></tr></tbody></table><hr><h2 id="_6-cross-reference-tai-lieu-lien-quan" tabindex="-1">6. Cross-reference (tài liệu liên quan) <a class="header-anchor" href="#_6-cross-reference-tai-lieu-lien-quan" aria-label="Permalink to &quot;6. Cross-reference (tài liệu liên quan)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Liên hệ với mảng Truyền thông online</th></tr></thead><tbody><tr><td><code>02-phan-mem-tong-crm.md</code></td><td>Phần mềm tổng / CRM — nơi mọi lead đổ về; 5 chức năng trung tâm (ID duy nhất, lịch sử trao đổi, tiến trình hồ sơ, tiến trình thanh toán, lưu trữ scan/biểu mẫu). Hạng mục 7 của sheet bám trực tiếp doc này.</td></tr><tr><td><code>03-web-chu-dau-tu.md</code></td><td>Web Chủ đầu tư (Nguồn 01) = &quot;Website tổng của công ty&quot; (hạng mục 1); đặc tả nội dung/media và form lead của website tổng.</td></tr><tr><td><code>04-web-noxh.md</code></td><td>Web NOXH (Nguồn 02) = &quot;Website sản phẩm NOXH&quot; (hạng mục 2); sheet dẫn &quot;Sheet 03&quot; cho phần công việc.</td></tr><tr><td><code>05-web-notm.md</code></td><td>Web NOTM (Nguồn 03) = &quot;Website sản phẩm NOTM&quot; (hạng mục 3); sheet dẫn &quot;Sheet 04&quot; cho phần công việc.</td></tr><tr><td><code>07-truyen-thong-truc-tiep.md</code></td><td>Truyền thông trực tiếp (Nguồn 04) — mảng song song; cùng nguyên tắc đổ lead về CRM theo một ID khách hàng.</td></tr><tr><td><code>09-open-questions.md</code></td><td>Tổng hợp toàn bộ OQ, gồm 4 câu OQ‑TTOL‑01…04 ở §5.</td></tr></tbody></table>',8))])}const T=e(u,[["render",l]]);export{B as __pageData,T as default};
